/*deleteMasterMpRqReqQuotReceipt_3*/
UPDATE	KEP_CMC_REQ
SET		REQ_STATUS = 'N',
		KEP_CMC_NOTE = KEP_CMC_NOTE || ' ' || TO_CHAR(SYSDATE, 'YYYY/MM/DD HH24:MI') || ' ' || #{st_cancel_note}, 
		CHANGE_DATE	= SYSDATE,
		CHANGE_USER_ID = #{USR_ID}
WHERE	1=1
AND		BUYER = #{BUYER}
AND		QUOTATION_NO = #{QUOTATION_NO}
AND		QUOTATION_SEQ = #{QUOTATION_SEQ}
AND		REVISION = #{REVISION}
AND		REQ_STATUS NOT IN ('B','C','D','N') -- B:발주후제출, C:승인, D:삭제, N:취소


UPDATE KEPRQDT	 /*updateSoMasterMpRqReqNegoReceipt*/				
   SET KEP_RFQ_FLAG      = DECODE(#{KEP_RFQ_FLAG},'1','Y','N')	
 WHERE BUYER          = #{BUYER}		
   AND QUOTATION_NO   = #{QUOTATION_NO}	
   AND QUOTATION_SEQ  = #{QUOTATION_SEQ}	
   AND REVISION       = #{REVISION}	
   AND STATUS IN ('C','R')


UPDATE KEPRQDT	A  /*updateMasterMpRqStndCatalg*/				
   SET CMS_CATLG_ID      = #{st_cms_catalgid}	
   , CATALOG_CHOICE_TYPE = #{CATALOG_CHOICE_TYPE}
   , IMGFILE_NAME = DECODE(#{st_imgfile_name},'' ,A.IMGFILE_NAME, #{st_imgfile_name}) 
   , IMGFILE_DIR = DECODE(#{st_imgfile_dir},'' ,A.IMGFILE_DIR, #{st_imgfile_dir})
   , RFQ_IMG_TYPE = DECODE(#{st_imgfile_dir},'' ,A.RFQ_IMG_TYPE, 'M')
 WHERE BUYER          = #{st_buyer}		
   AND QUOTATION_NO   = #{st_quotation_no}	
   AND QUOTATION_SEQ  = #{st_quotation_seq}	
   AND REVISION       = #{st_revision}


/*updateMasterMdCmStndCatalg*/
UPDATE ICOMBYIT	 				
   SET CMS_CATLG_ID      = #{st_cms_catalgid}
   , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
   , IMGFILE_NAME = #{st_imgfile_name}
   , IMGFILE_DIR = #{st_imgfile_dir}
   , CATALOG_CHOICE_TYPE = #{CATALOG_CHOICE_TYPE}	
 WHERE BUYER          = #{st_buyer}		
   AND BUYER_ITEM_NO   = #{st_buyer_item_no}


