SELECT	DECODE(COUNT(*), 0, 'N', 'Y') AS RPA_REG_YN
FROM	ICOMCQDT
WHERE	1=1
AND		BUYER = (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = #{BUYER})
AND		STATUS <> 'D'
AND		MAKER_CODE = #{MAKER_CODE}
AND		MAKER_PART_NO = #{MAKER_PART_NO}

