UPDATE	KEPRQDT /*updateMasterMpRqReqQuotReceiptForRPA1*/
SET		RPA_REG_YN = #{RPA_REG_YN},
		RPA_HIST_PRICE = DECODE(#{RPA_REG_YN}, 'N', 0, RPA_HIST_PRICE),
		RPA_MARKET_PRICE = #{RPA_MARKET_PRICE}
WHERE	1=1
AND		BUYER = #{BUYER}  
AND		QUOTATION_NO = #{QUOTATION_NO}
AND		QUOTATION_SEQ = #{QUOTATION_SEQ}
AND		REVISION = #{REVISION}
AND		STATUS <> 'D'


